import{_ as o,C as c,o as a,c as i,a4 as e,b as n,w as d,a as l,E as s,a5 as h}from"./chunks/framework.BRzJ4ijD.js";const C=JSON.parse('{"title":"CPU 流水线与指令级并行","description":"","frontmatter":{},"headers":[],"relativePath":"computer-arch/cpu-pipeline.md","filePath":"computer-arch/cpu-pipeline.md","lastUpdated":1788475713000}'),p={name:"computer-arch/cpu-pipeline.md"};function u(b,t,x,g,m,f){const r=c("Mermaid");return a(),i("div",null,[t[1]||(t[1]=e('<h1 id="cpu-流水线与指令级并行" tabindex="-1">CPU 流水线与指令级并行 <a class="header-anchor" href="#cpu-流水线与指令级并行" aria-label="Permalink to &quot;CPU 流水线与指令级并行&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>CPU 执行 <code>add x1, x2, x3</code> 不是原子瞬间完成的——它经过 <strong>取指 → 译码 → 执行 → 访存 → 写回</strong> 五阶段流水线。 理想状态下每 cycle 完成一条指令, 但 <strong>三种冒险 (hazard)</strong> 会打乱节奏:</p><ol><li><strong>结构冒险 (Structural)</strong>: 多指令争同一硬件资源 (如单端口 L1 cache)</li><li><strong>数据冒险 (Data)</strong>: 指令依赖前一条的结果 → forwarding / stalling</li><li><strong>控制冒险 (Control)</strong>: 分支跳转导致流水线等待 → branch prediction / speculative execution</li></ol><p>&quot;IPC = 1&quot; (每 cycle 一条) 在现实中被这三种冒险撞成 IPC ≈ 0.3-0.8 (单发射标量处理器)。 现代 CPU 通过 forwarding、branch predictor、speculation 来逼近 IPC=1。 本章推导 5-stage RISC pipeline 的每个 stage, 分析 hazards 与硬件修复代价, 最后落到真实 x86/ARM 核心 (Golden Cove、Zen 5 Cortex-X4 等等)。</p><hr><h2 id="一、5-stage-classic-risc-pipeline" tabindex="-1">一、5-stage Classic RISC Pipeline <a class="header-anchor" href="#一、5-stage-classic-risc-pipeline" aria-label="Permalink to &quot;一、5-stage Classic RISC Pipeline&quot;">​</a></h2><h3 id="risc-5-阶段" tabindex="-1">RISC 5 阶段 <a class="header-anchor" href="#risc-5-阶段" aria-label="Permalink to &quot;RISC 5 阶段&quot;">​</a></h3>',8)),(a(),n(h,null,{default:d(()=>[s(r,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20IF%5BIF%3A%20Instruction%20Fetch%3Cbr%2F%3E%E5%8F%96%E6%8C%87%5D%20--%3E%20ID%5BID%3A%20Instruction%20Decode%3Cbr%2F%3E%E8%AF%91%E7%A0%81%2B%E5%AF%84%E5%AD%98%E5%99%A8%20%E8%AF%BB%5D%0A%20%20%20%20ID%20--%3E%20EX%5BEX%3A%20Execute%3Cbr%2F%3EALU%20%E8%AE%A1%E7%AE%97%5D%0A%20%20%20%20EX%20--%3E%20MEM%5BMEM%3A%20Memory%20Access%3Cbr%2F%3E%E8%AE%BF%E5%AD%98(load%2Fstore)%5D%0A%20%20%20%20MEM%20--%3E%20WB%5BWB%3A%20Write%20Back%3Cbr%2F%3E%E5%86%99%E5%9B%9E%E5%AF%84%E5%AD%98%E5%99%A8%5D%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e(`<p>每个 stage 1 cycle, 每 cycle 一个组新指令 enters IF 同时前条指令移到下 stage。 所以 5 条指令可同时在流水线 (不同 stage), CPI = 1 (理想)。</p><h3 id="例子-ld-x1-0-x2-risc-v-load" tabindex="-1">例子: <code>ld x1, 0(x2)</code> (RISC-V load) <a class="header-anchor" href="#例子-ld-x1-0-x2-risc-v-load" aria-label="Permalink to &quot;例子: \`ld x1, 0(x2)\` (RISC-V load)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Cycle</th><th>IF</th><th>ID</th><th>EX</th><th>MEM</th><th>WB</th></tr></thead><tbody><tr><td>1</td><td><code>ld x1,0(x2)</code></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td><code>add x3,x4,x5</code></td><td><code>ld x1,0(x2)</code></td><td></td><td></td><td></td></tr><tr><td>3</td><td><code>sub x6,x7,x8</code></td><td><code>add x3,x4,x5</code></td><td><code>ld x1,0(x2)</code></td><td></td><td></td></tr><tr><td>4</td><td>...</td><td><code>sub x6,x7,x8</code></td><td><code>add x3,x4,x5</code></td><td><code>ld x1,0(x2)</code></td><td></td></tr><tr><td>5</td><td>...</td><td>...</td><td><code>sub x6,x7,x8</code></td><td><code>add x3,x4,x5</code></td><td><code>ld x1,0(x2)</code></td></tr></tbody></table><p>第 5 cycle 后 <code>x1</code> 数据才写回寄存器, <strong>后读该 x1 的指令必须等</strong>。</p><hr><h2 id="二、data-hazard-forwarding" tabindex="-1">二、Data Hazard &amp; Forwarding <a class="header-anchor" href="#二、data-hazard-forwarding" aria-label="Permalink to &quot;二、Data Hazard &amp; Forwarding&quot;">​</a></h2><h3 id="三种-data-hazard" tabindex="-1">三种 Data Hazard <a class="header-anchor" href="#三种-data-hazard" aria-label="Permalink to &quot;三种 Data Hazard&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>例</th><th>说明</th></tr></thead><tbody><tr><td>RAW (Read After Write)</td><td><code>add x1,x2,x3</code> → <code>sub x4,x1,x5</code></td><td>后条需要等前条写完 x1</td></tr><tr><td>WAR (Write After Read)</td><td><code>add x1,x2,x3</code> → <code>sub x2,x4,x5</code></td><td>后条写 x2 不能覆盖前条读 x2</td></tr><tr><td>WAW (Write After Write)</td><td><code>add x1,x2,x3</code> → <code>sub x1,x4,x5</code></td><td>两条都写 x1, 需保序</td></tr></tbody></table><p>WAR/WAW 主要用于 OoO 跑 (见下一章超标量); RAW 是 pipeline 最常见 hazard。</p><h3 id="forwarding-bypassing" tabindex="-1">Forwarding (Bypassing) <a class="header-anchor" href="#forwarding-bypassing" aria-label="Permalink to &quot;Forwarding (Bypassing)&quot;">​</a></h3><p><code>add x1,x2,x3</code> 在 EX 结束已经有了结果 (在第 3 cycle 末尾), 但 WB 才是第 5 cycle。 如果下条指令是 <code>sub x4,x1,x5</code>, 没必要等 WB——直接从 ALU output 绕过寄存器文件 forward 到下条 ALU input:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cycle 3: add EX (result in pipeline latch)</span></span>
<span class="line"><span>Cycle 4: sub EX — receives forwarded x1 from add latch (instead of WB register)</span></span></code></pre></div><p><strong>必须加 forwarding multiplexer</strong> + comparators 检查 dest register 与 src register 匹配。</p><h3 id="load-use-hazard" tabindex="-1">Load-Use Hazard <a class="header-anchor" href="#load-use-hazard" aria-label="Permalink to &quot;Load-Use Hazard&quot;">​</a></h3><p><code>ld x1,0(x2)</code> → value 在 MEM 结束后 (第 4 cycle 末) 才能用 而 <code>add x3,x1,x4</code> 在第 3 cycle EX 开始等不到。 一个 bubble (pipeline stall) 插等:</p><table tabindex="0"><thead><tr><th>Cycle</th><th>IF</th><th>ID</th><th>EX</th><th>MEM</th><th>WB</th></tr></thead><tbody><tr><td>3</td><td><code>add</code></td><td><code>ld</code> bubble</td><td><code>ld</code></td><td></td><td></td></tr><tr><td>4</td><td><code>add</code></td><td><code>ld</code> bubble</td><td>bubble(EX stall)</td><td><code>ld</code></td><td></td></tr><tr><td>5</td><td><code>add</code> 后指令</td><td><code>add</code> (check x1)</td><td>bubble</td><td>bubble</td><td><code>ld</code></td></tr></tbody></table><p>只能 stall 1 cycle, 不可能 forwarding 前 收 (MEM 值， EX 太早).</p><p>现代 CPU 编译 器可以重新排序 <code>ld</code> → <code>few independent instructions</code> → <code>use</code> 隐藏潜伏期。</p><hr><h2 id="三、control-hazard-branch-prediction" tabindex="-1">三、Control Hazard &amp; Branch Prediction <a class="header-anchor" href="#三、control-hazard-branch-prediction" aria-label="Permalink to &quot;三、Control Hazard &amp; Branch Prediction&quot;">​</a></h2><h3 id="分支代价" tabindex="-1">分支代价 <a class="header-anchor" href="#分支代价" aria-label="Permalink to &quot;分支代价&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>beq x1, x2, target</span></span></code></pre></div><p>第 3 cycle EX 结束才知道 taken or not。 但是直到第 3 cycle 结束 流水线 already fetched instruction after branch → 若 taken 则 两条 fetched 指令必须 flush。</p><p>Flush = 第 3-4 cycle 塞 NOP (no-op) = losing 2 cycles。</p><h3 id="branch-prediction-历史" tabindex="-1">Branch Prediction 历史 <a class="header-anchor" href="#branch-prediction-历史" aria-label="Permalink to &quot;Branch Prediction 历史&quot;">​</a></h3><table tabindex="0"><thead><tr><th>预测器</th><th>例</th><th>准确率</th></tr></thead><tbody><tr><td>Static (always not taken)</td><td>early RISC</td><td>~50%</td></tr><tr><td>1-bit BHT (Branch History Table)</td><td>单 bit T/NT selector</td><td>~80%</td></tr><tr><td>2-bit saturating counter</td><td>经典 &quot;双状态&quot; predictor</td><td>~90%</td></tr><tr><td>Gshare / Gselect (global history)</td><td>last N branch outcomes XOR with PC 选择预测</td><td>~95%</td></tr><tr><td>Tournament (hybrid)</td><td>多 predictor competition</td><td>~97%</td></tr><tr><td>TAGE (TAgged GEometric)</td><td>multi-length history, 近代: Haswell 起</td><td>~99%</td></tr><tr><td>Perceptron / Neural branch predictor</td><td>AMD Zen 4/5, Apple M3</td><td>~99.5%</td></tr></tbody></table><h3 id="_2-bit-saturating-counter" tabindex="-1">2-bit Saturating Counter <a class="header-anchor" href="#_2-bit-saturating-counter" aria-label="Permalink to &quot;2-bit Saturating Counter&quot;">​</a></h3><p>状态机:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>       taken</span></span>
<span class="line"><span>SNT ─→ WT ─→ ST</span></span>
<span class="line"><span>  ↑      ↓ taken</span></span>
<span class="line"><span>  └── WNT ←─ SNT (reset via not taken)</span></span></code></pre></div><p>四状态: Strongly Not Taken (00) → Weakly Not Taken (01) → Weakly Taken (10) → Strongly Taken (11)。 两个 not taken 后 从 WT 退到 WNT, 最后 not-taken 进 SNT。</p><h3 id="gshare-gselect" tabindex="-1">Gshare / Gselect <a class="header-anchor" href="#gshare-gselect" aria-label="Permalink to &quot;Gshare / Gselect&quot;">​</a></h3><p>Global branch history 寄存器 (GBHR): N 次最近 taken/not taken shift-in。 Gshare = XOR(PC[low bits], GBHR) → index BHT。 Gselect = concatenation。</p><p>Modern tournament: 多 predictor vote + 选择器 choose per branch。</p><h3 id="branch-target-buffer-btb" tabindex="-1">Branch Target Buffer (BTB) <a class="header-anchor" href="#branch-target-buffer-btb" aria-label="Permalink to &quot;Branch Target Buffer (BTB)&quot;">​</a></h3><p>BTB 存储了&quot;曾经 taken 的分支地址 → 目标地址&quot;映射: 在 IF 阶段就能读取 target PC, 不经等 EX 阶段算出。 第一道缓存: 命中 → fetch 立即转到 target。</p><h3 id="return-address-stack-ras" tabindex="-1">Return Address Stack (RAS) <a class="header-anchor" href="#return-address-stack-ras" aria-label="Permalink to &quot;Return Address Stack (RAS)&quot;">​</a></h3><p>函数返回 <code>ret</code> 是一个间接分支——每次 <code>call</code> 把 return_addr 推入 RAS LIFO stack; <code>ret</code> 就 predict top of RAS → 准确率 ~99.99%。</p><hr><h2 id="四、structural-hazard" tabindex="-1">四、Structural Hazard <a class="header-anchor" href="#四、structural-hazard" aria-label="Permalink to &quot;四、Structural Hazard&quot;">​</a></h2><h3 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to &quot;原因&quot;">​</a></h3><ul><li>单端口 L1 D-cache 不能同时读 (ID stage) 和 写 (MEM store stage)</li><li>寄存器文件单端口读 无法 multi 端口 支持同时向多 stage 读</li></ul><p>RISC 寄存器文件多端口解决。 Cache split I and D (L1 I-cache for IF + L1 D-cache for MEM), 只有在 store 时 单端口 structural hazard。</p><p>x86 寄存器名字少 (8×16+ → 32) — 但有 物理寄存器 大 (192+ 用于 OoO 改名)。</p><hr><h2 id="五、真实-cpu-流水线深度" tabindex="-1">五、真实 CPU 流水线深度 <a class="header-anchor" href="#五、真实-cpu-流水线深度" aria-label="Permalink to &quot;五、真实 CPU 流水线深度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>CPU</th><th>流水线深度</th><th>特点</th></tr></thead><tbody><tr><td>ARM Cortex-A53 (in-order)</td><td>8 stage</td><td>低功耗, IPC≤1</td></tr><tr><td>ARM Cortex-A78 (OoO)</td><td>10-15</td><td>dispatch → 8-wide decode</td></tr><tr><td>Apple M3 P-core (OoO)</td><td>~12-16</td><td>extreme 宽度 decode 9-wide</td></tr><tr><td>Intel Golden Cove (12th gen)</td><td>14-19 stages (complex decoded uops)</td><td>6-wide decode + 12 execution ports</td></tr><tr><td>AMD Zen 5</td><td>~19 stages (decode + uop cache)</td><td>dual 4-issue front-end</td></tr></tbody></table><p>深度 大 = 更高 clock rate (5GHz+) 但 mispredict penalty 也大 (19 cycle flush)。</p><hr><h2 id="六、micro-op-uop-与-macro-op-fusion" tabindex="-1">六、Micro-op (uop) 与 Macro-op Fusion <a class="header-anchor" href="#六、micro-op-uop-与-macro-op-fusion" aria-label="Permalink to &quot;六、Micro-op (uop) 与 Macro-op Fusion&quot;">​</a></h2><p>x86 是 CISC 指令集——<code>add [rax], rbx</code> (读 rax 存 memory) 是一个复杂 CISC 指令; decode 阶段 split 成 2-4 RISC-like μops:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>μop1: 计算地址 rax→pAddr</span></span>
<span class="line"><span>μop2: load  [pAddr] → tmp</span></span>
<span class="line"><span>μop3: add tmp, rbx</span></span>
<span class="line"><span>μop4: store result [pAddr]</span></span></code></pre></div><h3 id="宏融合-cmp-jcc-在-decode-时组合成一单-μop-compare-and-branch-比-两-μop-少-一半-dispatch。-intel-skylake-支持。" tabindex="-1">宏融合: <code>cmp+jcc</code> 在 decode 时组合成一单 μop <code>compare-and-branch</code>, 比 两 μop 少 一半 dispatch。 Intel Skylake+ 支持。 <a class="header-anchor" href="#宏融合-cmp-jcc-在-decode-时组合成一单-μop-compare-and-branch-比-两-μop-少-一半-dispatch。-intel-skylake-支持。" aria-label="Permalink to &quot;宏融合: \`cmp+jcc\` 在 decode 时组合成一单 μop \`compare-and-branch\`, 比 两 μop 少 一半 dispatch。 Intel Skylake+ 支持。&quot;">​</a></h3><h3 id="uop-cache-dsb" tabindex="-1">uop Cache (DSB) <a class="header-anchor" href="#uop-cache-dsb" aria-label="Permalink to &quot;uop Cache (DSB)&quot;">​</a></h3><p>Decoded Stream Buffer (Intel 内部): decoded μops 缓存; 遇到 1K+ hotspot loop → 从 μop cache 读, 绕过 decode pipeline → 省 2-3 cycle。 AMD Zen 3/4 有 &quot;Op Cache&quot; 类似。</p><hr><h2 id="七、典型事故" tabindex="-1">七、典型事故 <a class="header-anchor" href="#七、典型事故" aria-label="Permalink to &quot;七、典型事故&quot;">​</a></h2><h3 id="pentium-fdiv-bug-1994" tabindex="-1">Pentium FDIV Bug (1994) <a class="header-anchor" href="#pentium-fdiv-bug-1994" aria-label="Permalink to &quot;Pentium FDIV Bug (1994)&quot;">​</a></h3><p><code>FDIV</code> 引起 浮点除法 lookup table 部分错位 (4 entries missing 1066) — 1 in billions 错 误 指令。 Intel 召回 $475M。</p><h3 id="spectre-meltdown-2018" tabindex="-1">Spectre/Meltdown (2018) <a class="header-anchor" href="#spectre-meltdown-2018" aria-label="Permalink to &quot;Spectre/Meltdown (2018)&quot;">​</a></h3><p>Branch predictor speculation + &quot;load secret despite 训 坏 memory access&quot; − 侧信道攻击。 显示 speculative execution 泄露 敏感数据（side-channel）。 软件修补 → store bypass attack、retpolines， 性能损失 5-30%。</p><h3 id="arm-m1-virtualization-trap" tabindex="-1">ARM M1 Virtualization trap <a class="header-anchor" href="#arm-m1-virtualization-trap" aria-label="Permalink to &quot;ARM M1 Virtualization trap&quot;">​</a></h3><p>Apple M1 没有 x86 <code>TOTAL_STORE_ORDER</code> 内存模型, 运行 x86 translation 导致 额外 memory barrier, 性能 缺陷。 Rosetta 2 opt fix.</p><hr><h2 id="八、易错清单" tabindex="-1">八、易错清单 <a class="header-anchor" href="#八、易错清单" aria-label="Permalink to &quot;八、易错清单&quot;">​</a></h2><ol><li><strong>Load-use stall 无法 被 forwarding 消除</strong> — only next 指令 位置 reorder 可降。</li><li><strong>Branch predictor 99% 等于 still 1% flush</strong>: at GHz 率 1 秒 = 10M flush (每 flush ~19 cycle = 空过 190M missed cycles).</li><li><strong>μop 数量 不一定 省</strong>: <code>add [rax], rbx</code> 在 decode 分解 成 4 uops， 可慢 than 分离 load + reg op on RISC。</li><li><strong>BTB miss cost &gt; 2 cycle</strong>: 需 重算 分支地址， pipeline fill restart = 10-20 cycle.</li><li><strong>Write-after-write (WAW) 虽 pipeline raw 少 见， OoO 在 超标量 时常出现 → reg renaming 解。</strong></li></ol><hr><h2 id="九、这一章带走的东西" tabindex="-1">九、这一章带走的东西 <a class="header-anchor" href="#九、这一章带走的东西" aria-label="Permalink to &quot;九、这一章带走的东西&quot;">​</a></h2><ol><li>五阶段 pipeline: IF/ID/EX/MEM/WB；CPI=1 是 ideal, reals IPC 更有用.</li><li>Data hazards：forwarding 可解决 RAW 但 load-use 必须 stall.</li><li>Control hazards：branch prediction (2-bit / Gshare / TAGE / perceptron) + BTB + RAS.</li><li>流水线越深 → clock 高频, branch mispredict penalty ~19 cycle.</li><li>x86 μop decode: CISC→RISC 转 min 1 op, <code>add [reg], reg</code> 分解成 3-4 uops.</li><li>Spectre / Meltdown: speculative execution 允许 side-channel attack → OS/hardware fix → performance loss 5-30%.</li></ol><hr><p>下一节 → <a href="./cpu-superscalar">超标量 / OoO / Tomasulo</a></p>`,70))])}const A=o(p,[["render",u]]);export{C as __pageData,A as default};
